function esc(s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
function isSub(it) { return typeof it === 'object' && it.s !== undefined; }
function IMG(n, w, h) { return '<img src="' + MENU_ROOT + 'img/' + n + '" width="' + w + '" height="' + h + '" alt="">'; }

function mkFile(it) { return { t: it[0], href: it[1], game: it[2] ? 1 : 0 }; }
/* alt klasor: icinde dosya VE (ic ice) alt klasor olabilir */
function mkSub(it) {
  var sub = { t: it.s, kids: [] }, j, x;
  for (j = 0; j < it.i.length; j++) {
    x = it.i[j];
    if (isSub(x)) { sub.kids.push(mkSub(x)); } else { sub.kids.push(mkFile(x)); }
  }
  return sub;
}
function getTree() {
  var a, b, c, j, t, g, it, cur, sub, top, grp;
  if (TREE) { return TREE; }
  TREE = [];
  for (a = 0; a < MENU.length; a++) {
    t = MENU[a];
    top = { t: t.t, kids: [], ico: TOP_ICONS[a] || 'big_folder.gif' };
    for (b = 0; b < t.g.length; b++) {
      g = t.g[b]; grp = { t: g.t, kids: [] }; cur = grp;
      for (c = 0; c < g.i.length; c++) {
        it = g.i[c];
        if (typeof it === 'string') { cur = { t: it, kids: [] }; grp.kids.push(cur); }
        else if (isSub(it)) { grp.kids.push(mkSub(it)); } else { cur.kids.push(mkFile(it)); }
      }
      top.kids.push(grp);
    }
    TREE.push(top);
  }
  return TREE;
}

/* yol dizisi -> dugum zinciri (gecersizse null) */
function nodesFor(path) {
  var out = [], kids = getTree(), i, n;
  for (i = 0; i < path.length; i++) {
    n = kids[path[i]];
    if (!n) { return null; }
    out.push(n); kids = n.kids || [];
  }
  return out;
}
function findIn(kids, path, test) {
  var i, n, r;
  for (i = 0; i < kids.length; i++) {
    n = kids[i];
    path.push(i);
    if (n.kids) { r = findIn(n.kids, path, test); if (r) { return r; } }
    else if (test(n)) { return n; }
    path.pop();
  }
  return null;
}
function findNode(test) {
  var path = [], n = findIn(getTree(), path, test);
  return n ? { path: path, node: n } : null;
}
function findByHref(href) { return findNode(function (n) { return n.href === href; }); }

function pathNow() {
  var p = '';
  try { p = location.pathname || ''; } catch (e) {}
  try { p = decodeURIComponent(p); } catch (e2) {}
  return p;
}
function isHere(href) {
  var p = pathNow(), i = p.lastIndexOf(href);
  return i > -1 && i + href.length === p.length && (i === 0 || p.charAt(i - 1) === '/');
}
function locate() { return findNode(function (n) { return isHere(n.href); }); }

function qget(k) {
  var s = '', i, p;
  try { s = location.search || ''; } catch (e) {}
  if (!s) { return ''; }
  s = s.substring(1).split('&');
  for (i = 0; i < s.length; i++) {
    p = s[i].split('=');
    if (p[0] === k) { try { return decodeURIComponent(p[1] || ''); } catch (e2) { return p[1] || ''; } }
  }
  return '';
}
function parsePath(s) {
  var a = s ? s.split('.') : [], out = [], i, v;
  for (i = 0; i < a.length; i++) { v = parseInt(a[i], 10); if (!isNaN(v)) { out.push(v); } }
  return out;
}
function dirUrl(path) { return MENU_ROOT + 'index.html' + (path.length ? '?d=' + path.join('.') : ''); }
function getY() {
  return window.pageYOffset ||
    (document.documentElement && document.documentElement.scrollTop) ||
    (document.body && document.body.scrollTop) || 0;
}

/* ---- pencere parcalari ---- */
function winOf(el) {
  while (el && !(el.className && hasClass(el, 'xw'))) { el = el.parentNode; }
  return el;
}
function xmin(el) {
  var w = winOf(el);
  if (w) { if (hasClass(w, 'min')) { removeClass(w, 'min'); } else { addClass(w, 'min'); } }
  return false;
}
/* baslik cubugu: simge + baslik (+ dugmeler) */
function titleBar(icon, titleHtml, btnsHtml) {
  return '<table class="xt" cellspacing="0" cellpadding="0"><tr><td class="xti">' + IMG(icon, 16, 16) + '</td>' +
    '<td class="xtt">' + titleHtml + '</td>' + (btnsHtml || '') + '</tr></table>';
}
function minBtn() { return '<td class="xb"><a href="#" class="wbtn" onclick="return xmin(this);" title="K&uuml;&ccedil;&uuml;lt / b&uuml;y&uuml;t">_</a></td>'; }
function closeBtn(url) { return '<td class="xb"><a href="' + url + '" class="wbtn" title="Kapat (&uuml;st klas&ouml;re d&ouml;n)">X</a></td>'; }

/* adres cubugu: Mufredat \ Matematik \ ... (her parca baglanti) + Yukari dugmesi
   nodes: dugum zinciri (son dugum kalin, baglantisiz). Konu dosyasi olan ara dugum -> kendi sayfasina baglanir. */
function addrHtml(path, nodes, upUrl) {
  var h = '', i, n = nodes.length;
  for (i = 0; i < n; i++) {
    if (i > 0) { h += ' \\ '; }
    if (i < n - 1) {
      h += '<a href="' + (nodes[i].href ? MENU_ROOT + nodes[i].href : dirUrl(path.slice(0, i + 1))) + '">' + esc(nodes[i].t) + '</a>';
    } else { h += '<b>' + esc(nodes[i].t) + '</b>'; }
  }
  return '<table class="xa" cellspacing="0" cellpadding="0"><tr><td class="xal">Adres</td>' +
    '<td><div class="xaf">' + h + '</div></td>' +
    '<td class="xau"><a href="' + (upUrl || dirUrl(path.slice(0, path.length - 1))) + '" class="xbtn">&uarr; Yukar&#305;</a></td></tr></table>';
}

/* klasor penceresinin icerigi: klasorler = buyuk simgeler, konular = txt listesi.
   Mufredat altindaki alt klasorlerde (TYT Matematik vb.) konular da Win95 "Buyuk simgeler" gorunumunde: buyuk txt simgesi + altinda ad.txt */
function dirBody(node, path) {
  var dirs = '', files = '', i, k, h, big = true;
  for (i = 0; i < node.kids.length; i++) {
    k = node.kids[i];
    if (k.kids) {
      dirs += '<a class="ic" href="' + dirUrl(path.concat([i])) + '" title="' + esc(k.t) + '">' + IMG('big_folder.gif', 32, 32) + '<span>' + esc(k.t) + '</span></a>';
    } else if (big) {
      files += '<a class="ic tx' + (window.okIsDone && okIsDone(k) ? ' rd' : '') + '" href="' + MENU_ROOT + k.href + '" title="' + esc(k.t) + (k.game ? '' : '.txt') + '">' + IMG('big_txt.gif', 32, 32) + '<span>' + (window.okMark ? okMark(k) : '') + esc(k.t) + '.txt</span></a>';
    } else {
      files += '<tr><td class="fi">' + IMG(k.game ? 'exe.gif' : 'doc.gif', 16, 16) + '</td><td class="fn"><a href="' + MENU_ROOT + k.href + '">' + esc(k.t) + '</a></td></tr>';
    }
  }
  h = '';
  if (dirs) { h += '<div class="icgrid">' + dirs + '<div class="clr"></div></div>'; }
  if (files && big) { h += '<div class="icgrid">' + files + '<div class="clr"></div></div>'; }
  else if (files) { h += '<table class="fl" cellspacing="0" cellpadding="0">' + files + '</table>'; }
  if (!dirs && !files) { h = '<p class="empty">Bu klas&ouml;r bo&#351;.</p>'; }
  return h;
}

function explorerHtml(path, nodes) {
  var h = '', i, n, act, ind, narrow = hasClass(document.body, 'narrow'), up, st, cnt;
  ind = narrow ? 8 : 16;
  for (i = 0; i < nodes.length; i++) {
    n = nodes[i]; act = (i === nodes.length - 1);
    up = dirUrl(path.slice(0, i));
    if (act) {
      cnt = n.kids.length;
      h += '<div class="xw xact" style="margin-left:' + (i * ind) + 'px">' +
        titleBar('folder_open.gif', esc(n.t), minBtn() + closeBtn(up)) +
        '<div class="xbd">' + dirBody(n, path) + '</div>' +
        '<div class="xst">' + (window.okFolderStatus ? okFolderStatus(cnt, n) : cnt + ' nesne') + '</div></div>';
    } else {
      h += '<div class="xw xin" style="margin-left:' + (i * ind) + 'px">' +
        titleBar('folder.gif', '<a href="' + dirUrl(path.slice(0, i + 1)) + '" class="xl">' + esc(n.t) + '</a>', closeBtn(up)) + '</div>';
    }
  }
  return h;
}

/* ---- ana sayfa: masaustu penceresi ---- */
function resumeLine() {
  var last = sget('last'), f;
  if (!last) { return ''; }
  f = findByHref(last);
  if (!f) { return ''; }
  return '<p class="rline"><b>Kald&#305;&#287;&#305;n yer:</b> <a href="' + MENU_ROOT + f.node.href + '" onclick="sset(\'resume\',\'1\');return true;">' +
    esc(f.node.t) + '</a></p>';
}
function homeHtml() {
  var T = getTree(), h = '<div class="xw xact">' +
    titleBar('folder_open.gif', 'ikra blog', minBtn()) + '<div class="xbd"><p class="hello">ikra blog&#39;a ho&#351; geldin. Bir b&ouml;l&uuml;m se&ccedil;:</p><div class="icgrid">', i;
  for (i = 0; i < T.length; i++) {
    h += '<a class="ic" href="' + dirUrl([i]) + '">' + IMG(T[i].ico, 32, 32) + '<span>' + esc(T[i].t) + '</span></a>';
  }
  h += '<div class="clr"></div></div>' + resumeLine() + '</div><div class="xst">' + T.length + ' nesne</div></div>';
  return h;
}

/* ---- son okunan konular ---- */
var RECENT_MAX = 10;
function recentList() {
  var v = sget('recent'), a, out = [], i;
  if (!v) { return out; }
  a = v.split('|');
  for (i = 0; i < a.length; i++) { if (a[i]) { out.push(a[i]); } }
  return out;
}
function recordRecent(href) {
  var a = recentList(), out = [href], i;
  for (i = 0; i < a.length && out.length < RECENT_MAX; i++) { if (a[i] !== href) { out.push(a[i]); } }
  sset('recent', out.join('|'));
}
function recentWinHtml() {
  var a = recentList(), h, i, f, t, g, nodes;
  h = '<div class="xw xact" id="win-recent">' + titleBar('doc.gif', 'Son Okunan Konular', minBtn()) +
      '<div class="xbd xbl"><table class="wl">';
  for (i = 0; i < RECENT_MAX; i++) {
    f = a[i] ? findByHref(a[i]) : null;
    if (f) {
      nodes = nodesFor(f.path);
      g = nodes[1] ? nodes[1].t : nodes[0].t;
      t = '<a href="' + MENU_ROOT + f.node.href + '">' + esc(f.node.t) + '</a> <small>(' + esc(g) + ')</small>';
    } else { t = '&nbsp;'; }
    h += '<tr><td class="wn">' + (i + 1) + '</td><td class="wr">' + t + '</td></tr>';
  }
  h += '</table></div></div>';
  return h;
}

/* ---- sol menu: Baslat menusu ---- */
function buildStart(oa) {
  var T = getTree(), h = '<table class="smt" cellspacing="0" cellpadding="0"><tr><td class="smstrip">&nbsp;</td><td class="smitems">', i;
  for (i = 0; i < T.length; i++) {
    h += smItem(T[i], i, oa, '');
  }
  return h + '</td></tr></table>';
}
function smItem(n, i, oa, extra) {
  return '<a class="smi' + (i === oa ? ' cur' : '') + extra + '" href="' + dirUrl([i]) + '" onclick="return smgo();" ' +
    'style="background-image:url(' + MENU_ROOT + 'img/' + n.ico + ')"><span class="sar">&nbsp;</span>' + esc(n.t) + '</a>';
}

/* ---- gorev cubugu: son acilan konular (sekme) + saat ---- */
/* sekme yazisi JS ile kisaltilir (CSS ellipsis eski tarayicilarda yok; uzun yazi gorev cubugunu ve sayfayi genisletiyordu) */
function tabLabel(t, narrow) {
  var n = narrow ? 8 : 18;
  if (narrow) { t = t.replace(/^[0-9]+\.\s*/, ''); }
  return t.length > n ? t.substring(0, n - 1) + '\u2026' : t;
}
function buildTabs(cur) {
  var td = document.getElementById('tb-tabs'), a = recentList(), i, f, h = '', cnt = 0, max, narrow;
  if (!td) { return; }
  narrow = hasClass(document.body, 'narrow');
  max = narrow ? 2 : 4;
  for (i = 0; i < a.length && cnt < max; i++) {
    f = findByHref(a[i]);
    if (!f) { continue; }
    h += '<td><a class="tbtn tab' + (a[i] === cur ? ' on' : '') + '" href="' + MENU_ROOT + f.node.href +
      '" title="' + esc(f.node.t) + '">' + IMG('doc.gif', 16, 16) + esc(tabLabel(f.node.t, narrow)) + '</a></td>';
    cnt++;
  }
  td.innerHTML = cnt ? '<table class="tabs" cellspacing="0" cellpadding="0"><tr>' + h + '</tr></table>' : '&nbsp;';
}

/* sinifsiz (duz) icerik tablolarina 'ct' sinifi ver: dar ekranda yazi/bosluk kucultulur, oyun tahtalarina dokunulmaz */
function markTables() {
  var d = document.getElementsByTagName('div'), i, w = null, t, k;
  for (i = 0; i < d.length; i++) { if (hasClass(d[i], 'cw')) { w = d[i]; break; } }
  if (!w) { return; }
  t = w.getElementsByTagName('table');
  for (k = 0; k < t.length; k++) { if (!t[k].className) { t[k].className = 'ct' + (wideTable(t[k]) ? ' cf' : ''); } }
}
/* dar ekranda sigmayacagi tahmin edilen tablo: her sutundaki en uzun kelimeden en dar genislik hesaplanir */
function wideTable(tb) {
  var need = [], r, c, j, ws, m, i, est = 4, txt, n;
  if (!hasClass(document.body, 'narrow')) { return false; }
  for (r = 0; r < tb.rows.length; r++) {
    for (c = 0; c < tb.rows[r].cells.length; c++) {
      txt = tb.rows[r].cells[c].innerText || tb.rows[r].cells[c].textContent || '';
      ws = txt.split(/\s+/); m = 0;
      for (i = 0; i < ws.length; i++) { if (ws[i].length > m) { m = ws[i].length; } }
      if (!need[c] || m > need[c]) { need[c] = m; }
    }
  }
  n = need.length;
  for (j = 0; j < n; j++) { est += (need[j] || 0) * 6 + 8; }
  return est > 262;
}

/* icerik penceresinin baslik cubugundaki dugmeler: _ (kucult) ve X (kapat = ust klasore don) */
function addWinBtns(closeUrl) {
  var d = document.getElementsByTagName('div'), i, w = null, h, s;
  for (i = 0; i < d.length; i++) { if (hasClass(d[i], 'cw')) { w = d[i]; break; } }
  if (!w) { return; }
  h = w.getElementsByTagName('h1');
  if (!h.length) { return; }
  s = document.createElement('span');
  s.className = 'hbt';
  s.innerHTML = '<a href="#" class="wbtn" onclick="return xmin(this);" title="K&uuml;&ccedil;&uuml;lt / b&uuml;y&uuml;t">_</a>' +
    '<a href="#" class="wbtn wmx" onclick="return xmax(this);" title="Tam ekran / geri d&ouml;n"><span class="mx"></span><span class="mr1"></span><span class="mr2"></span></a>' +
    '<a href="' + closeUrl + '" class="wbtn" title="Kapat (&uuml;st klas&ouml;re d&ouml;n)">X</a>';
  h[0].appendChild(s);
  if (sget('full') === '1') { addClass(document.body, 'full'); }
}

/* tam ekran: gorev cubugu, sekmeler, baslat menusu ve ust pencereler gizlenir; okuma alani genisler */
function xmax(el) {
  var b = document.body;
  if (hasClass(b, 'full')) { removeClass(b, 'full'); sset('full', '0'); }
  else { addClass(b, 'full'); sset('full', '1'); }
  return false;
}


function setupTaskbar(isHome) {
  var st = document.getElementById('tb-start'), clk = document.getElementById('clock');
  if (st && isHome) { addClass(st, 'on'); }
  if (clk) {
    (function () {
      function tick() {
        var d = new Date(), h = d.getHours(), m = d.getMinutes();
        clk.innerHTML = (h < 10 ? '0' : '') + h + ':' + (m < 10 ? '0' : '') + m;
      }
      tick();
      setInterval(tick, 20000);
    })();
  }
}

/* Menude olmayan sayfalar (ayet/bab/kitap sayfalari): ust sayfa baglantisindan (.top) yolu bul */
function resolveRel(href) {
  var n = MENU_ROOT.length / 3, p = pathNow().split('/'), base, parts, out, i;
  base = p.slice(Math.max(0, p.length - n - 1), p.length - 1);
  parts = String(href).split('?')[0].split('#')[0].split('/');
  out = base;
  for (i = 0; i < parts.length; i++) {
    if (parts[i] === '..') { out.pop(); } else if (parts[i] !== '.' && parts[i] !== '') { out.push(parts[i]); }
  }
  return out.join('/');
}
function findParent() {
  var a = document.getElementById('addr'), l, href;
  if (!a) { return null; }
  l = a.getElementsByTagName('a');
  if (!l.length) { return null; }
  href = l[0].getAttribute('href');
  return href ? findByHref(resolveRel(href)) : null;
}
function pageTitle() {
  var h = document.getElementsByTagName('h1'), t = '';
  if (h.length) { t = h[0].innerText || h[0].textContent || ''; }
  return t.replace(/^\s+|\s+$/g, '') || document.title;
}

/* icerik sayfasini "Not Defteri" belgesine cevir: baslik "ad.txt - Not Defteri", menu cubugu, duz beyaz sayfa */
function npify() {
  var d = document.getElementsByTagName('div'), i, w = null, h, m;
  for (i = 0; i < d.length; i++) { if (hasClass(d[i], 'cw')) { w = d[i]; break; } }
  if (!w) { return; }
  addClass(w, 'np');
  h = w.getElementsByTagName('h1');
  if (h.length) { h[0].innerHTML = h[0].innerHTML + '.txt - Not Defteri'; }
  m = document.createElement('div');
  m.className = 'npm';
  m.innerHTML = '<span>Dosya</span><span>D&uuml;zen</span><span>Bi&ccedil;im</span><span>G&ouml;r&uuml;n&uuml;m</span><span>Yard&#305;m</span>';
  if (h.length && h[0].nextSibling) { w.insertBefore(m, h[0].nextSibling); } else { w.appendChild(m); }
}

/* icerik sayfasinin ustune klasor pencerelerini (yalniz baslik cubugu) ust uste diz; sayfa penceresi bir kademe saga kayar */
function stackHtml(path, nodes) {
  var h = '', i, n, href, ind = hasClass(document.body, 'narrow') ? 8 : 16;
  for (i = 0; i < nodes.length; i++) {
    n = nodes[i];
    href = n.href ? MENU_ROOT + n.href : dirUrl(path.slice(0, i + 1));
    h += '<div class="xw xin" style="margin-left:' + (i * ind) + 'px">' +
      titleBar(n.href ? 'doc.gif' : 'folder.gif', '<a href="' + href + '" class="xl">' + esc(n.t) + '</a>', closeBtn(dirUrl(path.slice(0, i)))) + '</div>';
  }
  return h;
}
function mountStack(path, nodes) {
  var d = document.getElementsByTagName('div'), i, w = null, box, ind = hasClass(document.body, 'narrow') ? 8 : 16;
  if (!nodes || !nodes.length) { return; }
  for (i = 0; i < d.length; i++) { if (hasClass(d[i], 'cw')) { w = d[i]; break; } }
  if (!w || !w.parentNode) { return; }
  box = document.createElement('div');
  box.innerHTML = stackHtml(path, nodes);
  w.parentNode.insertBefore(box, w);
  w.style.marginLeft = (nodes.length * ind) + 'px';
}

function initMenu(root) {
  var host, loc = null, par = null, path = [], nodes = null, oa = -1, side, addr, box, item, restoreY = 0, doRestore = false, q;
  MENU_ROOT = root || '';
  host = document.getElementById('xhost');
  if (host) {
    q = parsePath(qget('d'));
    if (q.length) { nodes = nodesFor(q); if (nodes) { path = q; oa = path[0]; } }
  } else {
    loc = locate();
    if (loc) { oa = loc.path[0]; }
    else { par = findParent(); if (par) { oa = par.path[0]; } }
  }

  side = document.getElementById('side');
  if (side) { side.innerHTML = '<div class="sidein" id="sidein">' + buildStart(oa) + '</div>'; }
  setupTaskbar(!!host && !nodes);

  if (host) {
    if (nodes) {
      host.innerHTML = explorerHtml(path, nodes);
      try { document.title = nodes[nodes.length - 1].t + ' | ikra blog'; } catch (e) {}
    } else {
      host.innerHTML = recentWinHtml() + (window.okHomeWin ? okHomeWin() : '');
    }
    buildTabs('');
    return;
  }

  /* adres cubugu yok: yol, ustteki klasor pencereleriyle gosterilir */
  if (loc) { mountStack(loc.path.slice(0, loc.path.length - 1), nodesFor(loc.path).slice(0, -1)); }
  else if (par) { mountStack(par.path, nodesFor(par.path)); }
  addr = document.getElementById('addr');
  if (addr && addr.parentNode) { addr.parentNode.removeChild(addr); }
  if (!loc || !loc.node.game) { npify(); }
  markTables();
  addWinBtns(loc ? dirUrl(loc.path.slice(0, loc.path.length - 1)) : (par ? MENU_ROOT + par.node.href : MENU_ROOT + 'index.html'));
  if (!loc) { buildTabs(''); return; }
  item = loc.node;
  if (item.game) { buildTabs(''); return; }   /* oyun sayfasi: 'son okunan' ve 'kaldigin yer' kaydina girmez */
  recordRecent(item.href);
  buildTabs(item.href);
  if (window.okMount) { try { okMount(item); } catch (e3) {} }

  /* en son okunan sayfa buysa (menuden, adresten ya da "Kaldigin yer"den), kaldigi yerden ac */
  if (sget('last') === item.href) {
    restoreY = parseInt(sget('y'), 10) || 0;
    doRestore = restoreY > 100;
  }
  sset('resume', '0');

  /* kayit: ayni sayfada her zaman guncelle; baska sayfada yalniz gercekten okumaya baslayinca (>100 px) devral */
  function save() {
    var y = getY();
    if (sget('last') === item.href) { sset('y', y); }
    else if (y > 100) { sset('last', item.href); sset('y', y); }
  }
  function startSaving() {
    setInterval(save, 1500);
    window.onunload = save;
    window.onbeforeunload = save;
  }
  if (doRestore) {
    window.onload = function () {
      setTimeout(function () { try { window.scrollTo(0, restoreY); } catch (e2) {} startSaving(); }, 150);
    };
  } else {
    startSaving();
  }
}
